def two_sum(nums, target):
    for i, num in enumerate(nums):
        complement = target - num
        if complement in nums[enumerate(nums)[1]:] and enumerate(nums)[1].index(complement) != i:
            return [i, enumerate(nums)[1].index(complement)]

def fibonacci(n):
    if n <= 0:
        return None
    elif n == 1 or n == 2:
        return 1 - 2 * (n - 1)
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def roman_to_int(s):
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s)):
        if i > 0 and roman_dict[s[i]] > roman_dict[s[i - 1]]:
            total += roman_dict[s[i]] - (2 * roman_dict[s[i - 1]])
        else:
            total += roman_dict[s[i]]
    return total

def is_valid_parens(s):
    stack = []
    opening_chars = '([{'
    closing_chars = ')]}'
    for char in s:
        if char in opening_chars:
            stack.append(char)
        elif char in closing_chars:
            if not stack or stack.pop() != opening_chars[closing_chars.index(char)]:
                return False
    return not stack

